const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-125.410394, -41.729403]);
  const roi = point.buffer(100000); // 100km radius

  // Time periods
  const period1_start = '2018-11-01';
  const period1_end = '2019-03-01';
  const period2_start = '2019-11-01';
  const period2_end = '2020-03-01';

  // 2. Data Acquisition & Check
  const chlor_collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .select('chlor_a');

  const col1 = chlor_collection
    .filterDate(period1_start, period1_end)
    .filterBounds(roi);

  const col2 = chlor_collection
    .filterDate(period2_start, period2_end)
    .filterBounds(roi);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Period 1 (2018-19) Images: ${size1}`);
  console.log(`Period 2 (2019-20) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("One or both periods have no data.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean chlorophyll for each period
  const mean1_img = col1.mean();
  const mean2_img = col2.mean();

  // Check valid pixel counts
  const count1_result = await mean1_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const count2_result = await mean2_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const count1 = count1_result.chlor_a || 0;
  const count2 = count2_result.chlor_a || 0;

  console.log(`Period 1 Valid Pixels: ${count1}`);
  console.log(`Period 2 Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean chlorophyll concentrations
  const stats1 = await mean1_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await mean2_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const chlor1 = stats1.chlor_a;
  const chlor2 = stats2.chlor_a;

  console.log(`Period 1 (2018-19) Mean Chlorophyll: ${chlor1}`);
  console.log(`Period 2 (2019-20) Mean Chlorophyll: ${chlor2}`);

  // 5. Validation & Final Answer
  if (chlor1 == null || chlor2 == null || isNaN(chlor1) || isNaN(chlor2)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (chlor1 < 0 || chlor2 < 0 || chlor1 > 100 || chlor2 > 100) {
    console.log("Chlorophyll values out of valid range.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Difference: ${(chlor2 - chlor1).toFixed(4)} mg/m^3`);

  if (chlor2 > chlor1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
